// VIOLATION: adding a new discount type requires modifying this class
class DiscountCalculator {
    double calculate(String type, double price) {
        if (type.equals("STUDENT")) return price * 0.8;
        if (type.equals("SENIOR")) return price * 0.7;
        // Adding EMPLOYEE discount requires changing this file
    }
}

// OCP: extend by adding new class, never touch DiscountCalculator
interface Discount { double apply(double price); }
class StudentDiscount implements Discount { public double apply(double p) { return p * 0.8; } }
class SeniorDiscount  implements Discount { public double apply(double p) { return p * 0.7; } }
// Add EmployeeDiscount without touching existing code

// Step 1: Define the interface
public interface NotificationSender {
    void send(String message, String recipient);
}

// Step 2: One class per implementation
public class EmailSender implements NotificationSender {
    public void send(String message, String recipient) { /* send email */ }
}
public class SmsSender implements NotificationSender {
    public void send(String message, String recipient) { /* send SMS */ }
}

// Step 3: Consumer depends on interface — never needs to change
public class NotificationService {
    private final NotificationSender sender; // inject via constructor
    public void notify(String msg, String to) { sender.send(msg, to); }
}
// Add WhatsAppSender without touching NotificationService

// Every new shape requires modifying this method
double calculateArea(Shape s) {
    if (s.type.equals("CIRCLE"))    return Math.PI * s.radius * s.radius;
    if (s.type.equals("RECTANGLE")) return s.width * s.height;
    if (s.type.equals("TRIANGLE"))  return 0.5 * s.base * s.height;
    // Add PENTAGON? Modify this file again
    throw new RuntimeException("Unknown shape");
}

// OCP fix: polymorphism
interface Shape { double area(); }
class Circle    implements Shape { public double area() { return Math.PI * r * r; } }
class Rectangle implements Shape { public double area() { return w * h; } }
// Add Pentagon by adding a class — existing code untouched
